-- Cold-chain shipment compliance schema (portable: PostgreSQL + SQLite).
-- Ground truth is stored outside the DB.
-- Intentionally NOT enforced here (validator's job): overlapping logger assignments,
-- reading-vs-assignment consistency, cross-row date coverage.
-- IDs are TEXT generated by code; timestamps are ISO-8601 UTC strings.

CREATE TABLE party (
  party_id   TEXT PRIMARY KEY,
  party_name TEXT NOT NULL UNIQUE,
  party_type TEXT NOT NULL CHECK (party_type IN ('SUPPLIER','CARRIER','WAREHOUSE'))
);

CREATE TABLE product (
  product_id            TEXT PRIMARY KEY,
  product_name          TEXT NOT NULL UNIQUE,
  category              TEXT NOT NULL CHECK (category IN ('VACCINE','BIOLOGIC','INSULIN','OTHER')),
  supplier_party_id     TEXT NOT NULL REFERENCES party(party_id),
  required_min_temp_c   NUMERIC(5,2) NOT NULL,
  required_max_temp_c   NUMERIC(5,2) NOT NULL,
  max_excursion_minutes INTEGER NOT NULL CHECK (max_excursion_minutes >= 0),
  created_at            TIMESTAMPTZ NOT NULL,
  CHECK (required_max_temp_c >= required_min_temp_c)
);

CREATE TABLE lot (
  lot_id             TEXT PRIMARY KEY,
  product_id         TEXT NOT NULL REFERENCES product(product_id),
  manufacturing_date DATE NOT NULL,
  expiry_date        DATE NOT NULL,
  lot_status         TEXT NOT NULL CHECK (lot_status IN ('CREATED','RELEASED','QUARANTINED','EXPIRED')),
  created_at         TIMESTAMPTZ NOT NULL,
  CHECK (expiry_date > manufacturing_date)
);

CREATE TABLE packaging (
  packaging_id             TEXT PRIMARY KEY,
  packaging_type           TEXT NOT NULL,
  min_supported_temp_c     NUMERIC(5,2) NOT NULL,
  max_supported_temp_c     NUMERIC(5,2) NOT NULL,
  qualified_duration_hours INTEGER NOT NULL CHECK (qualified_duration_hours > 0),
  packaging_status         TEXT NOT NULL CHECK (packaging_status IN ('ACTIVE','RETIRED')),
  CHECK (max_supported_temp_c >= min_supported_temp_c)
);

CREATE TABLE logger (
  logger_id                 TEXT PRIMARY KEY,
  device_serial_number      TEXT NOT NULL UNIQUE,
  calibration_status        TEXT NOT NULL CHECK (calibration_status IN ('VALID','EXPIRED','UNCALIBRATED')),
  calibration_date          DATE,
  calibration_expiry        DATE,
  calibration_uncertainty_c NUMERIC(4,2) CHECK (calibration_uncertainty_c >= 0),
  device_status             TEXT NOT NULL CHECK (device_status IN ('AVAILABLE','IN_USE','MAINTENANCE','RETIRED')),
  CHECK (calibration_date IS NULL OR calibration_expiry IS NULL OR calibration_expiry >= calibration_date)
);

CREATE TABLE logger_calibration (
  calibration_id TEXT PRIMARY KEY,
  logger_id      TEXT NOT NULL REFERENCES logger(logger_id),
  calibrated_on  DATE NOT NULL,
  expires_on     DATE NOT NULL,
  uncertainty_c  NUMERIC(4,2) NOT NULL CHECK (uncertainty_c >= 0),
  UNIQUE (logger_id, calibrated_on),
  CHECK (expires_on > calibrated_on)
);

CREATE TABLE threshold_policy (
  policy_id                 TEXT PRIMARY KEY,
  product_id                TEXT NOT NULL REFERENCES product(product_id),
  policy_version            INTEGER NOT NULL CHECK (policy_version >= 1),
  min_temp_c                NUMERIC(5,2) NOT NULL,
  max_temp_c                NUMERIC(5,2) NOT NULL,
  max_excursion_minutes     INTEGER NOT NULL CHECK (max_excursion_minutes >= 0),
  max_data_gap_minutes      INTEGER NOT NULL CHECK (max_data_gap_minutes > 0),
  sampling_interval_minutes INTEGER NOT NULL CHECK (sampling_interval_minutes > 0),
  max_dwell_minutes         INTEGER NOT NULL CHECK (max_dwell_minutes >= 0),
  effective_from            TIMESTAMPTZ NOT NULL,
  effective_to              TIMESTAMPTZ,
  policy_status             TEXT NOT NULL CHECK (policy_status IN ('DRAFT','ACTIVE','SUPERSEDED','RETIRED')),
  UNIQUE (product_id, policy_version),
  CHECK (max_temp_c >= min_temp_c),
  CHECK (effective_to IS NULL OR effective_to > effective_from)
);

CREATE TABLE shipment (
  shipment_id          TEXT PRIMARY KEY,
  product_id           TEXT NOT NULL REFERENCES product(product_id),
  policy_id            TEXT NOT NULL REFERENCES threshold_policy(policy_id),
  origin_location      TEXT NOT NULL,
  destination_location TEXT NOT NULL,
  origin_party_id      TEXT NOT NULL REFERENCES party(party_id),
  destination_party_id TEXT NOT NULL REFERENCES party(party_id),
  planned_departure    TIMESTAMPTZ NOT NULL,
  planned_arrival      TIMESTAMPTZ NOT NULL,
  departure_time       TIMESTAMPTZ,
  arrival_time         TIMESTAMPTZ,
  shipment_status      TEXT NOT NULL CHECK (shipment_status IN ('PLANNED','PACKED','IN_TRANSIT','DELIVERED','CANCELLED')),
  created_at           TIMESTAMPTZ NOT NULL,
  CHECK (destination_location <> origin_location),
  CHECK (planned_arrival > planned_departure),
  CHECK (departure_time IS NULL OR arrival_time IS NULL OR arrival_time >= departure_time)
);

CREATE TABLE shipment_status_history (
  history_id  TEXT PRIMARY KEY,
  shipment_id TEXT NOT NULL REFERENCES shipment(shipment_id),
  from_status TEXT CHECK (from_status IS NULL OR from_status IN ('PLANNED','PACKED','IN_TRANSIT','DELIVERED','CANCELLED')),
  to_status   TEXT NOT NULL CHECK (to_status IN ('PLANNED','PACKED','IN_TRANSIT','DELIVERED','CANCELLED')),
  changed_at  TIMESTAMPTZ NOT NULL,
  changed_by  TEXT
);

CREATE TABLE shipment_lot (
  shipment_id    TEXT NOT NULL REFERENCES shipment(shipment_id),
  lot_id         TEXT NOT NULL REFERENCES lot(lot_id),
  quantity_units INTEGER NOT NULL CHECK (quantity_units > 0),
  PRIMARY KEY (shipment_id, lot_id)
);

CREATE TABLE shipment_packaging (
  shipment_id   TEXT NOT NULL REFERENCES shipment(shipment_id),
  packaging_id  TEXT NOT NULL REFERENCES packaging(packaging_id),
  assigned_from TIMESTAMPTZ NOT NULL,
  assigned_to   TIMESTAMPTZ,
  PRIMARY KEY (shipment_id, packaging_id, assigned_from),
  CHECK (assigned_to IS NULL OR assigned_to >= assigned_from)
);

CREATE TABLE logger_assignment (
  logger_assignment_id TEXT PRIMARY KEY,
  logger_id            TEXT NOT NULL REFERENCES logger(logger_id),
  shipment_id          TEXT NOT NULL REFERENCES shipment(shipment_id),
  assigned_from        TIMESTAMPTZ NOT NULL,
  assigned_to          TIMESTAMPTZ,
  assignment_status    TEXT NOT NULL CHECK (assignment_status IN ('ASSIGNED','COMPLETED','CANCELLED')),
  UNIQUE (shipment_id, logger_id, assigned_from),
  CHECK (assigned_to IS NULL OR assigned_to >= assigned_from)
);

CREATE TABLE temperature_reading (
  reading_id                TEXT PRIMARY KEY,
  logger_id                 TEXT NOT NULL REFERENCES logger(logger_id),
  logger_assignment_id      TEXT REFERENCES logger_assignment(logger_assignment_id),
  recorded_at               TIMESTAMPTZ NOT NULL,
  received_at               TIMESTAMPTZ NOT NULL,
  temperature_c             NUMERIC(5,2) NOT NULL CHECK (temperature_c BETWEEN -80 AND 60),
  calibration_uncertainty_c NUMERIC(4,2) NOT NULL CHECK (calibration_uncertainty_c >= 0),
  reading_quality           TEXT NOT NULL CHECK (reading_quality IN ('GOOD','SUSPECT','INVALID')),
  UNIQUE (logger_id, recorded_at),
  CHECK (received_at >= recorded_at)
);

CREATE TABLE custody_event (
  custody_event_id TEXT PRIMARY KEY,
  shipment_id      TEXT NOT NULL REFERENCES shipment(shipment_id),
  event_sequence   INTEGER NOT NULL CHECK (event_sequence >= 1),
  from_party_id    TEXT REFERENCES party(party_id),
  to_party_id      TEXT REFERENCES party(party_id),
  event_type       TEXT NOT NULL CHECK (event_type IN ('PICKUP','HANDOVER','DELIVERY')),
  event_timestamp  TIMESTAMPTZ NOT NULL,
  recorded_at      TIMESTAMPTZ NOT NULL,
  location         TEXT,
  UNIQUE (shipment_id, event_sequence),
  CHECK (recorded_at >= event_timestamp)
);

CREATE TABLE route_stop (
  route_stop_id     TEXT PRIMARY KEY,
  shipment_id       TEXT NOT NULL REFERENCES shipment(shipment_id),
  location          TEXT NOT NULL,
  stop_type         TEXT NOT NULL CHECK (stop_type IN ('ORIGIN','TRANSIT','DESTINATION')),
  stop_sequence     INTEGER,
  actual_sequence   INTEGER,
  planned_arrival   TIMESTAMPTZ,
  planned_departure TIMESTAMPTZ,
  actual_arrival    TIMESTAMPTZ,
  actual_departure  TIMESTAMPTZ,
  CHECK (planned_arrival IS NULL OR planned_departure IS NULL OR planned_departure >= planned_arrival),
  CHECK (actual_arrival IS NULL OR actual_departure IS NULL OR actual_departure >= actual_arrival),
  CHECK (planned_arrival IS NOT NULL OR actual_arrival IS NOT NULL)
);

CREATE TABLE compliance_run (
  compliance_run_id            TEXT PRIMARY KEY,
  shipment_id                  TEXT NOT NULL REFERENCES shipment(shipment_id),
  policy_id                    TEXT NOT NULL REFERENCES threshold_policy(policy_id),
  policy_version               INTEGER NOT NULL,
  policy_min_temp_c            NUMERIC(5,2) NOT NULL,
  policy_max_temp_c            NUMERIC(5,2) NOT NULL,
  policy_max_excursion_minutes INTEGER NOT NULL,
  policy_max_data_gap_minutes  INTEGER NOT NULL,
  compliance_status            TEXT NOT NULL CHECK (compliance_status IN ('COMPLIANT','NON_COMPLIANT','INDETERMINATE')),
  reason_summary               TEXT NOT NULL,
  engine_version               TEXT NOT NULL,
  input_fingerprint            TEXT NOT NULL,
  run_at                       TIMESTAMPTZ NOT NULL,
  is_current                   BOOLEAN NOT NULL DEFAULT TRUE,
  UNIQUE (shipment_id, input_fingerprint)
);

CREATE TABLE compliance_finding (
  finding_id        TEXT PRIMARY KEY,
  compliance_run_id TEXT NOT NULL REFERENCES compliance_run(compliance_run_id),
  rule_code         TEXT NOT NULL,
  result            TEXT NOT NULL CHECK (result IN ('PASS','FAIL','INDETERMINATE','WARNING')),
  detail            TEXT NOT NULL,
  detail_json       TEXT
);

CREATE TABLE compliance_evidence (
  finding_id TEXT NOT NULL REFERENCES compliance_finding(finding_id),
  reading_id TEXT NOT NULL REFERENCES temperature_reading(reading_id),
  PRIMARY KEY (finding_id, reading_id)
);

CREATE TABLE excursion_report (
  excursion_id         TEXT PRIMARY KEY,
  shipment_id          TEXT NOT NULL REFERENCES shipment(shipment_id),
  logger_id            TEXT REFERENCES logger(logger_id),
  logger_assignment_id TEXT REFERENCES logger_assignment(logger_assignment_id),
  policy_id            TEXT REFERENCES threshold_policy(policy_id),
  compliance_run_id    TEXT REFERENCES compliance_run(compliance_run_id),
  source               TEXT NOT NULL CHECK (source IN ('LEGACY_IMPORT','ENGINE')),
  issue_type           TEXT NOT NULL CHECK (issue_type IN ('TEMP_HIGH','TEMP_LOW','MISSING_DATA','LOGGER_NOT_ASSIGNED','CALIBRATION_INVALID','ASSIGNMENT_OVERLAP','POLICY_MISMATCH','CUSTODY_GAP','ROUTE_DEVIATION','CROSS_SHIPMENT_REPORT','CALIBRATION_MARGINAL')),
  start_time           TIMESTAMPTZ,
  end_time             TIMESTAMPTZ,
  duration_minutes     INTEGER CHECK (duration_minutes >= 0),
  peak_temperature_c   NUMERIC(5,2),
  severity             TEXT NOT NULL CHECK (severity IN ('LOW','MEDIUM','HIGH','CRITICAL')),
  status               TEXT NOT NULL CHECK (status IN ('OPEN','ASSIGNED','INVESTIGATING','RESOLVED','ESCALATED')),
  detected_at          TIMESTAMPTZ NOT NULL,
  assigned_analyst     TEXT,
  resolution           TEXT,
  resolved_at          TIMESTAMPTZ,
  evidence_reference   TEXT,
  CHECK (start_time IS NULL OR end_time IS NULL OR end_time >= start_time)
);

CREATE TABLE excursion_evidence (
  excursion_id TEXT NOT NULL REFERENCES excursion_report(excursion_id),
  reading_id   TEXT NOT NULL REFERENCES temperature_reading(reading_id),
  PRIMARY KEY (excursion_id, reading_id)
);

CREATE TABLE exception_event (
  exception_event_id TEXT PRIMARY KEY,
  excursion_id       TEXT NOT NULL REFERENCES excursion_report(excursion_id),
  from_status        TEXT,
  to_status          TEXT NOT NULL CHECK (to_status IN ('OPEN','ASSIGNED','INVESTIGATING','RESOLVED','ESCALATED')),
  analyst            TEXT,
  note               TEXT,
  occurred_at        TIMESTAMPTZ NOT NULL
);

CREATE TABLE legacy_report (
  legacy_report_id TEXT PRIMARY KEY,
  shipment_id      TEXT NOT NULL REFERENCES shipment(shipment_id),
  reported_status  TEXT NOT NULL CHECK (reported_status IN ('PASS','FAIL')),
  reported_by      TEXT NOT NULL,
  reported_at      TIMESTAMPTZ NOT NULL
);

CREATE INDEX idx_reading_logger_time ON temperature_reading(logger_id, recorded_at);
CREATE INDEX idx_assignment_logger_from ON logger_assignment(logger_id, assigned_from);
CREATE INDEX idx_assignment_shipment ON logger_assignment(shipment_id);
CREATE INDEX idx_custody_shipment ON custody_event(shipment_id);
CREATE INDEX idx_route_stop_shipment ON route_stop(shipment_id);
CREATE INDEX idx_excursion_shipment ON excursion_report(shipment_id);
CREATE INDEX idx_run_shipment ON compliance_run(shipment_id);
CREATE INDEX idx_shipment_status ON shipment(shipment_status);
